Object.assign(copy.pl,{studioAlt:'Wizja kamiennej siedziby pracowni TERREN otoczonej ogrodem',studioImageNote:'WIZJA PRACOWNI / TERREN',studioLabel:'O STUDIU',studioTitle:'ARCHITEKTURA.<br>NATURA. CZŁOWIEK.',studioLead:'Najciekawsze miejsca powstają tam, gdzie kończy się pośpiech, a zaczyna uważność.',studioText:'TERREN to pracownia architektury krajobrazu. Interesuje nas ogród jako naturalne przedłużenie domu — przestrzeń, która ma własny rytm, charakter i sposób bycia. Zaczynamy od miejsca. Jego światła, proporcji, drzew i tego, co już w nim istnieje.',studioText2:'Łączymy porządek architektury ze swobodą natury. Lubimy materiały, które pięknie się starzeją, rośliny, które zmieniają się z porami roku, i rozwiązania, które pozostają aktualne długo po pierwszym zachwycie.',studioLink:'POZNAJ NASZE PODEJŚCIE',offerLabel:'ZAKRES WSPÓŁPRACY',offerTitle:'OD POMYSŁU DO OGRODU',offerIntro:'Każdy ogród potrzebuje innej drogi.<br>Wybieramy tę, która ma sens dla Twojego miejsca.',offer1:'KONCEPCJA<br>OGRODU',offer1Text:'Pierwszy, spójny obraz miejsca. Układ przestrzeni, proporcje, atmosfera i relacja ogrodu z architekturą.',offer1Detail:'IDEA · KOMPOZYCJA · KIERUNEK',offer2:'PROJEKT<br>KOMPLEKSOWY',offer2Text:'Przekładamy pomysł na szczegóły. Opracowujemy ścieżki, tarasy, strefy odpoczynku i rozwiązania do realizacji.',offer2Detail:'FUNKCJA · DETAL · DOKUMENTACJA',offer3:'ROŚLINY<br>I MATERIAŁY',offer3Text:'Dobór zieleni i naturalnych faktur. Myślimy o świetle, sezonowości, warunkach miejsca i pielęgnacji.',offer3Detail:'NASADZENIA · FAKTURY · SEZONY',offer4:'WSPARCIE<br>REALIZACJI',offer4Text:'Towarzyszymy projektowi na etapie wykonania. Pomagamy zachować jego charakter w materiałach, roślinach i detalach.',offer4Detail:'KONSULTACJE · SPÓJNOŚĆ · JAKOŚĆ',breakAlt:'Ogród z oliwkami, cyprysami i spokojną taflą wody',breakLabel:'PRZESTRZEŃ NA CODZIENNOŚĆ',breakTitle:'DOBRZE JEST<br>PO PROSTU BYĆ.',approachLabel:'NASZE PODEJŚCIE',approachTitle:'NAJPIERW MIEJSCE.<br>POTEM PROJEKT.',approachIntro:'Dobra współpraca zaczyna się od rozmowy. Przechodzimy od pytań do decyzji — spokojnie, krok po kroku.',process1:'ROZMOWA I OBSERWACJA',process1Text:'Poznajemy Twoje potrzeby i czytamy krajobraz. Przyglądamy się temu, jak żyjesz i jak chcesz korzystać z ogrodu.',process2:'WSPÓLNY KIERUNEK',process2Text:'Tworzymy koncepcję, która porządkuje przestrzeń i buduje jej atmosferę. Rozmawiamy o proporcjach, funkcjach i materiałach.',process3:'SZCZEGÓŁY I REALIZACJA',process3Text:'Dopracowujemy projekt i dobór roślin. Ustalamy kolejne kroki, aby pomysł mógł stać się żywym, dojrzewającym ogrodem.',questionsLabel:'WARTO WIEDZIEĆ',questionsTitle:'ZANIM ZACZNIEMY',question1:'Kiedy warto zacząć projekt ogrodu?',answer1:'Już na etapie projektu domu lub planowania zmian na działce. Wspólne myślenie o architekturze i ogrodzie pozwala lepiej połączyć wnętrze z otoczeniem. Istniejący ogród również może być dobrym początkiem.',question2:'Co przygotować przed pierwszą rozmową?',answer2:'Zdjęcia miejsca, przybliżoną powierzchnię, plan działki, jeśli go masz, i kilka słów o swoich potrzebach. Inspiracje są pomocne, ale równie ważne jest to, jak chcesz spędzać czas na zewnątrz.',question3:'Czy ogród może być piękny przez cały rok?',answer3:'Projektujemy kompozycje, które mają coś do zaoferowania w każdej porze roku. Zimowa struktura drzew, zieleń krzewów, kwitnienie i jesienne faktury tworzą różne odsłony tego samego miejsca.',contactLabel:'TWÓJ NASTĘPNY KROK',contactHeading:'ZACZNIJMY<br>OD ROZMOWY.',contactCopy:'Opowiedz nam o miejscu, które chcesz zmienić.<br>Resztę odkryjemy wspólnie.',contactCta:'PRZYGOTUJ BRIEF'});
Object.assign(copy.en,{studioAlt:'A vision of the TERREN stone studio surrounded by a garden',studioImageNote:'A STUDIO VISION / TERREN',studioLabel:'THE STUDIO',studioTitle:'ARCHITECTURE.<br>NATURE. PEOPLE.',studioLead:'The most interesting places begin where the rush ends and attention takes over.',studioText:'TERREN is a landscape architecture studio. We see a garden as a natural extension of home — a space with its own rhythm, character, and way of being. We begin with the place. Its light, proportions, trees, and everything that already belongs there.',studioText2:'We bring architectural clarity together with the freedom of nature. We value materials that age beautifully, plants that change with the seasons, and ideas that remain relevant long after the first impression.',studioLink:'DISCOVER OUR APPROACH',offerLabel:'HOW WE CAN HELP',offerTitle:'FROM IDEA TO GARDEN',offerIntro:'Every garden needs a different path.<br>We find the one that makes sense for your place.',offer1:'GARDEN<br>CONCEPT',offer1Text:'A coherent first vision. Spatial layout, proportions, atmosphere, and the relationship between garden and architecture.',offer1Detail:'IDEA · COMPOSITION · DIRECTION',offer2:'COMPLETE<br>DESIGN',offer2Text:'We develop the details. Paths, terraces, places to rest, and considered solutions ready to bring the garden to life.',offer2Detail:'FUNCTION · DETAIL · DOCUMENTATION',offer3:'PLANTS<br>& MATERIALS',offer3Text:'Greenery and natural textures, chosen with light, seasonality, site conditions, and care in mind.',offer3Detail:'PLANTING · TEXTURES · SEASONS',offer4:'PROJECT<br>SUPPORT',offer4Text:'We stay involved as the garden takes shape, helping preserve its character in materials, planting, and details.',offer4Detail:'CONSULTATION · COHERENCE · QUALITY',breakAlt:'A garden with olive trees, cypresses, and a quiet reflecting pool',breakLabel:'ROOM FOR EVERYDAY LIFE',breakTitle:'A PLACE<br>TO SIMPLY BE.',approachLabel:'OUR APPROACH',approachTitle:'FIRST, THE PLACE.<br>THEN, THE DESIGN.',approachIntro:'Good collaboration begins with a conversation. We move from questions to decisions — thoughtfully, one step at a time.',process1:'CONVERSATION & OBSERVATION',process1Text:'We learn about your needs and read the landscape. We consider how you live and how you want to use your garden.',process2:'A SHARED DIRECTION',process2Text:'We create a concept that organises the space and shapes its atmosphere. Together, we explore proportions, functions, and materials.',process3:'DETAILS & REALISATION',process3Text:'We refine the design and planting choices, setting out the next steps towards a living garden that matures with time.',questionsLabel:'GOOD TO KNOW',questionsTitle:'BEFORE WE BEGIN',question1:'When should a garden project begin?',answer1:'Ideally, while designing the house or planning changes to the site. Considering architecture and garden together creates a stronger connection between indoors and out. An existing garden can be an equally good starting point.',question2:'What should I prepare for our first conversation?',answer2:'Photos, an approximate area, a site plan if you have one, and a few words about your needs. References are helpful, but how you want to spend time outdoors matters just as much.',question3:'Can a garden be beautiful throughout the year?',answer3:'We create compositions with something to offer in every season. The winter structure of trees, evergreen planting, flowers, and autumn textures reveal different sides of the same place.',contactLabel:'YOUR NEXT STEP',contactHeading:'LET’S START<br>A CONVERSATION.',contactCopy:'Tell us about the place you want to transform.<br>We will discover the rest together.',contactCta:'PREPARE YOUR BRIEF'});
copy.pl.cities.push('POZNAŃ','GDAŃSK');copy.en.cities.push('POZNAŃ','GDAŃSK');copy.pl.descriptions.push('Spokojna tafla wody i ogród w ciepłym świetle.','Miękkie trawy, jasny kamień i swoboda krajobrazu.');copy.en.descriptions.push('Quiet water and a garden in warm evening light.','Soft grasses, pale stone, and an open landscape.');copy.pl.alts.push('Koncepcja ogrodu z lustrem wody','Koncepcja ogrodu z trawami i kamiennym pawilonem');copy.en.alts.push('Reflecting pool garden concept','Garden concept with grasses and a stone pavilion');
Object.assign(copy.pl,{studioShort:'TERREN to pracownia architektury krajobrazu. Tworzymy ogrody, które łączą spokojną geometrię z naturalnym rytmem roślin.',studioCity:'WARSZAWA',studioSince:'OD 2018 ROKU',offerHeading:'OFERTA',offer1:'KONCEPCJA OGRODU',offer1Text:'Spójny pomysł na przestrzeń, jej atmosferę i relację z domem.',offer1Detail:'IDEA · KOMPOZYCJA',offer2:'PROJEKT KOMPLEKSOWY',offer2Text:'Układ ogrodu, nawierzchnie i detale przygotowane do realizacji.',offer2Detail:'FUNKCJA · DETAL',offer3:'ROŚLINY I MATERIAŁY',offer3Text:'Nasadzenia i faktury dobrane do miejsca oraz jego pór roku.',offer3Detail:'ZIELEŃ · FAKTURY',offer4:'WSPARCIE REALIZACJI',offer4Text:'Uważność na etapie wykonania — od pierwszych prac po ostatnie nasadzenia.',offer4Detail:'SPÓJNOŚĆ · JAKOŚĆ',breakAlt:'Włoski ogród z otwartą taflą wody i odbiciami cyprysów',waterPause:'ZATRZYMAJ WODĘ',waterPlay:'WZNÓW WODĘ',approachNewTitle:'KAŻDY OGRÓD MA SWÓJ RYTM',approach1:'SŁUCHAMY',approach1Text:'Ciebie, miejsca i jego codzienności.',approach2:'PORZĄDKUJEMY',approach2Text:'Przestrzeń, proporcje i to, co najważniejsze.',approach3:'DAJEMY ROSNĄĆ',approach3Text:'Ogrodom, które dojrzewają z czasem.',contactHeading:'ZACZNIJMY OD ROZMOWY',contactCopy:'Kilka słów o Tobie i miejscu, które chcesz zmienić.',formName:'Imię i nazwisko',formEmail:'Adres e-mail',formPhone:'Telefon — opcjonalnie',formMessage:'Opowiedz o swoim ogrodzie',formSend:'WYŚLIJ ZAPYTANIE',formDemo:'Formularz demonstracyjny. Dane nie są wysyłane.'});
Object.assign(copy.en,{studioShort:'TERREN is a landscape architecture studio. We create gardens that bring quiet geometry together with the natural rhythm of plants.',studioCity:'WARSAW',studioSince:'SINCE 2018',offerHeading:'SERVICES',offer1:'GARDEN CONCEPT',offer1Text:'A coherent idea for the space, its atmosphere, and its relationship with home.',offer1Detail:'IDEA · COMPOSITION',offer2:'COMPLETE DESIGN',offer2Text:'Garden layout, surfaces, and details prepared for implementation.',offer2Detail:'FUNCTION · DETAIL',offer3:'PLANTS & MATERIALS',offer3Text:'Planting and textures chosen for the place and its changing seasons.',offer3Detail:'PLANTING · TEXTURES',offer4:'PROJECT SUPPORT',offer4Text:'Care throughout implementation — from the first groundwork to the last planting.',offer4Detail:'COHERENCE · QUALITY',breakAlt:'Italian garden with open water and reflected cypress trees',waterPause:'PAUSE WATER',waterPlay:'RESUME WATER',approachNewTitle:'EVERY GARDEN HAS ITS OWN RHYTHM',approach1:'WE LISTEN',approach1Text:'To you, the place, and its everyday life.',approach2:'WE COMPOSE',approach2Text:'Space, proportions, and what matters most.',approach3:'WE LET IT GROW',approach3Text:'Gardens that become richer with time.',contactHeading:'LET’S START A CONVERSATION',contactCopy:'A few words about you and the place you want to transform.',formName:'Full name',formEmail:'Email address',formPhone:'Phone — optional',formMessage:'Tell us about your garden',formSend:'SEND ENQUIRY',formDemo:'Demonstration form. No information is sent.'});
Object.assign(copy.pl,{studioStory:'Najciekawsze miejsca powstają tam, gdzie kończy się pośpiech, a zaczyna uważność. TERREN to pracownia architektury krajobrazu z Warszawy. Od 2016 roku tworzymy ogrody dla osób, które szukają własnego miejsca blisko natury. Zaczynamy od rozmowy o codzienności — porannej kawie, spotkaniach przy stole i chwilach, kiedy dobrze jest po prostu pobyć na zewnątrz. Łączymy spokojną geometrię z naturalnym rytmem roślin. Przyglądamy się światłu, istniejącym drzewom i relacji ogrodu z domem, żeby całość miała swój charakter i dobrze dojrzewała przez kolejne lata.',studioSince:'OD 2016 ROKU',breakTitle:'DOBRZE JEST PO PROSTU BYĆ.',materialsAlt:'Kamień, drewno i zieleń w pracowni TERREN',materialsLabel:'MATERIAŁ, ŚWIATŁO, CZAS',materialsTitle:'PIĘKNO, KTÓRE DOJRZEWA',materialsIntro:'Wybieramy to, co z czasem staje się jeszcze ciekawsze. Ogród ma dobrze wyglądać dzisiaj i równie dobrze żyć za kilka lat.',material1:'KAMIEŃ',material1Text:'Naturalna faktura, spokojne proporcje i patyna, która opowiada historię miejsca.',material2:'DREWNO',material2Text:'Ciepło pod stopami, miękki kolor i detal, który dobrze łączy dom z ogrodem.',material3:'ZIELEŃ',material3Text:'Drzewa, trawy i byliny budujące kolejne warstwy krajobrazu — od wiosny do zimy.',contactBreakAlt:'Trawy i byliny w popołudniowym świetle',contactBreakText:'BLISKO NATURY. BLISKO CIEBIE.'});
Object.assign(copy.en,{studioStory:'The most interesting places begin where the rush ends and attention takes over. TERREN is a landscape architecture studio based in Warsaw. Since 2016, we have created gardens for people looking for their own place close to nature. We begin by talking about everyday life — morning coffee, gathering around a table, and moments when it feels good simply to be outdoors. We combine quiet geometry with the natural rhythm of plants. We consider the light, existing trees, and the relationship between garden and home, giving each place a character that grows richer with time.',studioSince:'SINCE 2016',breakTitle:'A PLACE TO SIMPLY BE.',materialsAlt:'Stone, wood, and greenery at the TERREN studio',materialsLabel:'MATERIAL, LIGHT, TIME',materialsTitle:'BEAUTY THAT MATURES',materialsIntro:'We choose things that become more interesting with time. A garden should look beautiful today and live just as well in the years ahead.',material1:'STONE',material1Text:'Natural texture, quiet proportions, and a patina that tells the story of a place.',material2:'WOOD',material2Text:'Warmth underfoot, a soft colour, and details that connect home with garden.',material3:'PLANTING',material3Text:'Trees, grasses, and perennials building layers of landscape — from spring to winter.',contactBreakAlt:'Grasses and perennials in afternoon light',contactBreakText:'CLOSE TO NATURE. CLOSE TO YOU.'});
const images=['assets/italian-garden.jpg','assets/meadow.jpg','assets/courtyard.jpg','assets/reflecting-garden.jpg','assets/hero.jpg'];
const count=images.length,reduced=matchMedia('(prefers-reduced-motion: reduce)');
let lang='pl',current=0,paused=false,physical=count,animating=false,manualHold=0,pointerInside=false,carouselVisible=false;
const track=document.querySelector('#carousel-track'),region=document.querySelector('.carousel');
const t=key=>copy[lang][key];
function updateCounter(){document.querySelector('#current-slide').textContent=String(current+1).padStart(2,'0');document.querySelector('#slide-total').textContent=String(count).padStart(2,'0');track.querySelectorAll('.project').forEach(el=>el.classList.toggle('active',Number(el.dataset.index)===current));}
function positionTrack(animate=false){const mobile=matchMedia('(max-width:600px)').matches;const width=region.clientWidth*(mobile?.82:.30),gap=mobile?18:28;track.style.setProperty('--card-width',`${width}px`);track.style.setProperty('--card-gap',`${gap}px`);track.style.transition=animate&&!reduced.matches?'transform 850ms cubic-bezier(.22,.61,.36,1)':'none';track.style.transform=`translate3d(${region.clientWidth/2-width/2-physical*(width+gap)}px,0,0)`;}
function renderCarousel(){physical=count+current;animating=false;track.innerHTML=Array.from({length:count*3},(_,i)=>{const index=i%count;return `<figure class="project" data-index="${index}" ${i<count||i>=count*2?'aria-hidden="true"':''} role="group" aria-roledescription="slide" aria-label="${index+1} / ${count} — ${t('cities')[index]}"><div class="project-image"><img src="${images[index]}" alt="${t('alts')[index]}" draggable="false" width="1536" height="1024" loading="lazy"><span class="roman">${['I','II','III','IV','V'][index]}</span></div><figcaption><h3>${t('cities')[index]}</h3><p>${t('descriptions')[index]}</p></figcaption></figure>`}).join('');positionTrack();updateCounter();}
function finishMovement(){animating=false;if(physical<count||physical>=count*2){physical=count+current;positionTrack(false)}}
track.addEventListener('transitionend',e=>{if(e.propertyName==='transform')finishMovement()});
let motionSerial=0; function move(direction,manual=true){if(animating)return;const serial=++motionSerial;current=(current+direction+count)%count;physical+=direction;animating=!reduced.matches;positionTrack(true);updateCounter();if(reduced.matches)finishMovement();else setTimeout(()=>{if(animating&&motionSerial===serial)finishMovement()},950);if(manual)manualHold=Date.now()+3500;}
function updatePause(){const b=document.querySelector('#pause');b.setAttribute('aria-pressed',String(paused));b.querySelector('[data-i18n]').textContent=t(paused?'play':'pause');b.querySelector('.pause-icon').textContent=paused?'▷':'Ⅱ';}
function setLanguage(next,persist=true){lang=next in copy?next:'pl';document.documentElement.lang=lang;document.title=t('title');document.querySelectorAll('[data-i18n]').forEach(el=>el.innerHTML=t(el.dataset.i18n));document.querySelectorAll('[data-alt]').forEach(el=>el.alt=t(el.dataset.alt));document.querySelectorAll('[data-lang]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.lang===lang)));document.querySelector('#previous').ariaLabel=t('previous');document.querySelector('#next').ariaLabel=t('next');region.ariaLabel=t('carousel');document.querySelector('.status').textContent='';renderCarousel();updatePause();updateWater();if(persist)try{localStorage.setItem('terren-language',lang)}catch{}}
document.querySelectorAll('[data-lang]').forEach(b=>b.addEventListener('click',()=>setLanguage(b.dataset.lang)));
document.querySelector('#previous').addEventListener('click',()=>move(-1));document.querySelector('#next').addEventListener('click',()=>move(1));document.querySelector('#pause').addEventListener('click',()=>{paused=!paused;updatePause()});region.addEventListener('keydown',e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();move(e.key==='ArrowRight'?1:-1)}});region.addEventListener('mouseenter',()=>pointerInside=true);region.addEventListener('mouseleave',()=>pointerInside=false);
let startX=null;region.addEventListener('pointerdown',e=>{startX=e.clientX;manualHold=Date.now()+3500});region.addEventListener('pointerup',e=>{if(startX!==null&&Math.abs(e.clientX-startX)>40)move(e.clientX<startX?1:-1);startX=null});region.addEventListener('pointercancel',()=>startX=null);region.addEventListener('pointerleave',()=>startX=null);
new IntersectionObserver(entries=>carouselVisible=entries[0].isIntersecting,{threshold:.3}).observe(region);setInterval(()=>{if(!paused&&carouselVisible&&!document.hidden&&Date.now()>manualHold)move(1,false)},4000);window.addEventListener('resize',()=>{physical=count+current;animating=false;positionTrack()});
let waterPaused=reduced.matches;
function updateWater(){document.querySelector('.garden-break').classList.toggle('water-still',waterPaused);const b=document.querySelector('#water-toggle');b.setAttribute('aria-pressed',String(waterPaused));b.querySelector('[data-i18n]').textContent=t(waterPaused?'waterPlay':'waterPause');const svg=document.querySelector('#water-filters');if(waterPaused)svg.pauseAnimations?.();else svg.unpauseAnimations?.();}
document.querySelector('#water-toggle').addEventListener('click',()=>{waterPaused=!waterPaused;updateWater()});
reduced.addEventListener('change',e=>{waterPaused=e.matches;updateWater()});
document.querySelector('#contact-button').addEventListener('click',()=>document.querySelector('#kontakt').scrollIntoView({behavior:reduced.matches?'auto':'smooth'}));
document.querySelector('#contact-form').addEventListener('submit',e=>{e.preventDefault();document.querySelector('.status').textContent=t('formDemo')});
try{setLanguage(localStorage.getItem('terren-language')||'pl',false)}catch{setLanguage('pl',false)}document.querySelector('#year').textContent=new Date().getFullYear();




